import { Todo } from '../domain/todo';
import { TodoRepository } from '../domain/todo-repository';

export class TodoService {
  constructor(private readonly repo: TodoRepository) {}

  overdue(now: number): Todo[] {
    const all = this.repo.findAll();
    const out: Todo[] = [];
    for (const t of all) {
      if (!t.done && t.due < now && t.due > 0) {
        out.push(t);
      }
    }
    return out;
  }

  complete(id: string): void {
    const t = this.repo.findById(id);
    if (t !== undefined) t.done = true;
  }
}

export function isLate(t: Todo, now: number): boolean {
  if (t.done) {
    return false;
  }
  const late = t.due < now && t.due > 0;
  return late && now - t.due > 1000;
}

